[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. Always free for patients.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --navy: #1B1464;
      --navy-light: #2a1f8e;
      --navy-dark: #120e45;
      --accent: #FFD930;
      --accent-hover: #f5cf1a;
      --green: #00B67A;
      --green-hover: #009e6a;
      --white: #FFFFFF;
      --gray-50: #F8F9FC;
      --gray-100: #F1F3F8;
      --gray-200: #E2E6EF;
      --gray-300: #C8CFD8;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --gray-900: #111827;
      --radius: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 2px rgba(27, 20, 100, 0.05);
      --shadow-md: 0 4px 12px rgba(27, 20, 100, 0.08);
      --shadow-lg: 0 8px 30px rgba(27, 20, 100, 0.12);
      --shadow-xl: 0 16px 50px rgba(27, 20, 100, 0.15);
      --font: 'Inter', system-ui, -apple-system, sans-serif;
      --transition: 200ms ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      color: var(--gray-800);
      background: var(--white);
      line-height: 1.6;
      font-size: 16px;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      overflow-x: hidden;
    }

    /* ─── HEADER ─── */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid transparent;
      transition: border-color 0.3s, box-shadow 0.3s;
    }
    .header.scrolled {
      border-bottom-color: var(--gray-200);
      box-shadow: var(--shadow-sm);
    }
    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      text-decoration: none;
      font-weight: 800;
      font-size: 1.5rem;
      color: var(--navy);
    }
    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--navy);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--accent);
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 8px;
      list-style: none;
    }
    .nav-links a {
      text-decoration: none;
      color: var(--gray-600);
      font-weight: 500;
      font-size: 0.938rem;
      padding: 8px 16px;
      border-radius: 8px;
      transition: background var(--transition), color var(--transition);
    }
    .nav-links a:hover { background: var(--gray-50); color: var(--navy); }
    .nav-btn {
      background: var(--navy) !important;
      color: var(--white) !important;
      padding: 8px 20px !important;
    }
    .nav-btn:hover { background: var(--navy-light) !important; }

    .hamburger {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      color: var(--navy);
      padding: 8px;
    }

    /* ─── MOBILE MENU ─── */
    .mobile-overlay {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.4);
      z-index: 2000;
      opacity: 0;
      transition: opacity 0.3s;
    }
    .mobile-overlay.open { opacity: 1; }

    .mobile-menu {
      position: fixed;
      top: 0;
      right: 0;
      bottom: 0;
      width: 300px;
      max-width: 85vw;
      background: var(--white);
      z-index: 2001;
      transform: translateX(100%);
      transition: transform 0.3s ease;
      padding: 24px;
      display: flex;
      flex-direction: column;
    }
    .mobile-menu.open { transform: translateX(0); }

    .mobile-menu-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 32px;
    }
    .mobile-close {
      background: none;
      border: none;
      cursor: pointer;
      color: var(--gray-500);
      padding: 4px;
    }
    .mobile-nav-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .mobile-nav-links a {
      text-decoration: none;
      color: var(--gray-700);
      font-weight: 500;
      font-size: 1.1rem;
      padding: 14px 16px;
      border-radius: 10px;
      display: block;
      transition: background var(--transition);
    }
    .mobile-nav-links a:hover { background: var(--gray-50); }
    .mobile-nav-links .mobile-signup {
      background: var(--navy);
      color: var(--white);
      text-align: center;
      margin-top: 12px;
      border-radius: 10px;
    }
    .mobile-nav-links .mobile-signup:hover { background: var(--navy-light); }

    /* ─── HERO ─── */
    .hero {
      padding: 140px 24px 80px;
      background: linear-gradient(170deg, #f0edff 0%, #ffffff 50%, #fffce8 100%);
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -200px;
      width: 600px;
      height: 600px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(27,20,100,0.04) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: -100px;
      left: -150px;
      width: 400px;
      height: 400px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(255,217,48,0.1) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero-content {
      max-width: 720px;
      margin: 0 auto;
      position: relative;
      z-index: 1;
    }
    .hero h1 {
      font-size: clamp(2.2rem, 5vw, 3.5rem);
      font-weight: 800;
      color: var(--navy);
      line-height: 1.15;
      margin-bottom: 20px;
      letter-spacing: -0.03em;
    }
    .hero p {
      font-size: clamp(1rem, 2vw, 1.2rem);
      color: var(--gray-600);
      max-width: 580px;
      margin: 0 auto 40px;
      line-height: 1.7;
    }

    /* ─── SEARCH BAR ─── */
    .search-container {
      max-width: 780px;
      margin: 0 auto;
      position: relative;
      z-index: 10;
    }
    .search-bar {
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-xl);
      padding: 8px;
      display: flex;
      align-items: center;
      gap: 4px;
      border: 2px solid transparent;
      transition: border-color 0.3s;
    }
    .search-bar:focus-within {
      border-color: var(--navy);
    }
    .search-field {
      flex: 1;
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 12px 16px;
      border-radius: 10px;
      min-width: 0;
      position: relative;
    }
    .search-field:hover { background: var(--gray-50); }
    .search-field i { color: var(--gray-400); flex-shrink: 0; }
    .search-field input,
    .search-field select {
      border: none;
      outline: none;
      background: transparent;
      font-family: var(--font);
      font-size: 0.938rem;
      color: var(--gray-800);
      width: 100%;
      min-width: 0;
    }
    .search-field input::placeholder,
    .search-field select { color: var(--gray-400); }
    .search-field select option { color: var(--gray-800); }
    .search-divider {
      width: 1px;
      height: 32px;
      background: var(--gray-200);
      flex-shrink: 0;
    }
    .search-btn {
      background: var(--green);
      color: var(--white);
      border: none;
      border-radius: 10px;
      padding: 14px 28px;
      font-family: var(--font);
      font-weight: 600;
      font-size: 1rem;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 8px;
      transition: background var(--transition), transform 150ms;
      flex-shrink: 0;
    }
    .search-btn:hover { background: var(--green-hover); }
    .search-btn:active { transform: scale(0.97); }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      left: -8px;
      right: -8px;
      background: var(--white);
      border-radius: var(--radius);
      box-shadow: var(--shadow-lg);
      border: 1px solid var(--gray-200);
      overflow: hidden;
      display: none;
      z-index: 100;
    }
    .autocomplete-dropdown.visible { display: block; }
    .autocomplete-item {
      padding: 12px 16px;
      display: flex;
      align-items: center;
      gap: 12px;
      cursor: pointer;
      transition: background 150ms;
      font-size: 0.938rem;
    }
    .autocomplete-item:hover { background: var(--gray-50); }
    .autocomplete-item i { color: var(--gray-400); }
    .autocomplete-item .label { color: var(--gray-800); }
    .autocomplete-item .type { color: var(--gray-400); font-size: 0.813rem; margin-left: auto; }

    /* ─── SECTION SHARED ─── */
    .section {
      padding: 80px 24px;
    }
    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .section-title {
      font-size: clamp(1.6rem, 3vw, 2.2rem);
      font-weight: 800;
      color: var(--navy);
      text-align: center;
      margin-bottom: 12px;
      letter-spacing: -0.02em;
    }
    .section-subtitle {
      text-align: center;
      color: var(--gray-500);
      font-size: 1.05rem;
      max-width: 520px;
      margin: 0 auto 48px;
    }

    /* ─── SPECIALTIES ─── */
    .specialties { background: var(--white); }
    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }
    .specialty-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 28px 24px;
      display: flex;
      align-items: center;
      gap: 16px;
      text-decoration: none;
      color: var(--gray-800);
      transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
      cursor: pointer;
    }
    .specialty-card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow-md);
      border-color: var(--navy);
    }
    .specialty-icon {
      width: 52px;
      height: 52px;
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 1.4rem;
    }
    .specialty-icon.primary { background: #EDE9FE; color: #6D28D9; }
    .specialty-icon.teal { background: #CCFBF1; color: #0D9488; }
    .specialty-icon.pink { background: #FCE7F3; color: #DB2777; }
    .specialty-icon.blue { background: #DBEAFE; color: #2563EB; }
    .specialty-icon.amber { background: #FEF3C7; color: #D97706; }
    .specialty-icon.green { background: #D1FAE5; color: #059669; }
    .specialty-info h3 {
      font-weight: 600;
      font-size: 1.05rem;
      margin-bottom: 2px;
      color: var(--gray-800);
    }
    .specialty-info p {
      font-size: 0.875rem;
      color: var(--gray-500);
      line-height: 1.5;
    }

    /* ─── STATS BAR ─── */
    .stats-bar {
      background: var(--navy);
      padding: 48px 24px;
      overflow: hidden;
    }
    .stats-inner {
      max-width: 1000px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      text-align: center;
    }
    .stat-item {
      color: var(--white);
    }
    .stat-number {
      font-size: clamp(1.8rem, 3.5vw, 2.6rem);
      font-weight: 800;
      color: var(--accent);
      letter-spacing: -0.02em;
      line-height: 1.2;
    }
    .stat-label {
      font-size: 0.938rem;
      color: rgba(255,255,255,0.75);
      margin-top: 6px;
      font-weight: 500;
    }

    /* ─── HOW IT WORKS ─── */
    .how-it-works { background: var(--gray-50); }
    .steps-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      position: relative;
    }
    .step-card {
      text-align: center;
      padding: 32px 24px;
      position: relative;
    }
    .step-number {
      width: 56px;
      height: 56px;
      border-radius: 50%;
      background: var(--navy);
      color: var(--accent);
      display: inline-flex;
      align-items: center;
      justify-content: center;
      font-weight: 800;
      font-size: 1.3rem;
      margin-bottom: 20px;
    }
    .step-card h3 {
      font-size: 1.15rem;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 10px;
    }
    .step-card p {
      font-size: 0.938rem;
      color: var(--gray-500);
      line-height: 1.65;
    }
    .step-connector {
      display: none;
    }

    /* ─── TESTIMONIALS ─── */
    .testimonials { background: var(--white); }
    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }
    .testimonial-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 32px;
      transition: transform var(--transition), box-shadow var(--transition);
    }
    .testimonial-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }
    .testimonial-stars {
      color: var(--accent);
      font-size: 1.1rem;
      margin-bottom: 16px;
      letter-spacing: 2px;
    }
    .testimonial-text {
      font-size: 1rem;
      color: var(--gray-700);
      line-height: 1.7;
      margin-bottom: 20px;
      font-style: italic;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .testimonial-avatar {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 1rem;
      color: var(--navy);
    }
    .testimonial-name {
      font-weight: 600;
      font-size: 0.938rem;
      color: var(--gray-800);
    }
    .testimonial-location {
      font-size: 0.813rem;
      color: var(--gray-400);
    }

    /* ─── APP PROMO ─── */
    .app-promo {
      background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%);
      padding: 80px 24px;
      color: var(--white);
      overflow: hidden;
      position: relative;
    }
    .app-promo::before {
      content: '';
      position: absolute;
      top: -100px;
      right: -50px;
      width: 350px;
      height: 350px;
      border-radius: 50%;
      background: rgba(255,217,48,0.08);
      pointer-events: none;
    }
    .app-promo-inner {
      max-width: 1100px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
      position: relative;
      z-index: 1;
    }
    .app-promo-text h2 {
      font-size: clamp(1.8rem, 3.5vw, 2.5rem);
      font-weight: 800;
      margin-bottom: 16px;
      letter-spacing: -0.02em;
    }
    .app-promo-text p {
      font-size: 1.05rem;
      color: rgba(255,255,255,0.8);
      margin-bottom: 32px;
      line-height: 1.7;
    }
    .app-features {
      list-style: none;
      margin-bottom: 36px;
      display: grid;
      gap: 14px;
    }
    .app-features li {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 0.975rem;
      color: rgba(255,255,255,0.9);
    }
    .app-features li i {
      color: var(--accent);
      flex-shrink: 0;
    }
    .app-buttons {
      display: flex;
      gap: 14px;
      flex-wrap: wrap;
    }
    .app-btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      background: var(--white);
      color: var(--navy);
      text-decoration: none;
      padding: 14px 24px;
      border-radius: 12px;
      font-weight: 600;
      font-size: 0.938rem;
      transition: transform 150ms, box-shadow var(--transition);
    }
    .app-btn:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(0,0,0,0.2);
    }
    .app-btn i { font-size: 1.2rem; }
    .app-mockup {
      display: flex;
      justify-content: center;
      align-items: center;
    }
    .phone-frame {
      width: 260px;
      height: 500px;
      background: linear-gradient(160deg, #2a1f8e, #1B1464);
      border-radius: 36px;
      padding: 12px;
      box-shadow: 0 30px 60px rgba(0,0,0,0.3);
      position: relative;
    }
    .phone-screen {
      width: 100%;
      height: 100%;
      background: var(--white);
      border-radius: 26px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }
    .phone-header {
      background: var(--navy);
      color: var(--white);
      padding: 20px 16px 16px;
      text-align: center;
    }
    .phone-header .phone-logo {
      font-weight: 700;
      font-size: 0.875rem;
      margin-bottom: 10px;
      color: var(--accent);
    }
    .phone-search {
      background: rgba(255,255,255,0.15);
      border-radius: 8px;
      padding: 8px 12px;
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 0.75rem;
      color: rgba(255,255,255,0.6);
    }
    .phone-content {
      padding: 16px;
      flex: 1;
    }
    .phone-section-title {
      font-size: 0.7rem;
      font-weight: 700;
      color: var(--gray-600);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 10px;
    }
    .phone-card-mini {
      background: var(--gray-50);
      border-radius: 10px;
      padding: 10px 12px;
      margin-bottom: 8px;
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .phone-card-mini .dot {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      flex-shrink: 0;
    }
    .phone-card-mini .lines {
      display: flex;
      flex-direction: column;
      gap: 4px;
      flex: 1;
    }
    .phone-card-mini .line {
      height: 6px;
      border-radius: 3px;
      background: var(--gray-200);
    }
    .phone-card-mini .line.short { width: 60%; }
    .phone-card-mini .line.long { width: 85%; }

    /* ─── FOOTER ─── */
    .footer {
      background: var(--gray-900);
      color: rgba(255,255,255,0.7);
      padding: 64px 24px 32px;
    }
    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 1.4fr repeat(4, 1fr);
      gap: 40px;
      margin-bottom: 48px;
    }
    .footer-brand .logo {
      color: var(--white);
      margin-bottom: 12px;
      display: inline-flex;
    }
    .footer-brand p {
      font-size: 0.875rem;
      line-height: 1.6;
      color: rgba(255,255,255,0.5);
    }
    .footer-col h4 {
      color: var(--white);
      font-size: 0.875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 16px;
    }
    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    .footer-col a {
      text-decoration: none;
      color: rgba(255,255,255,0.5);
      font-size: 0.875rem;
      transition: color var(--transition);
    }
    .footer-col a:hover { color: var(--white); }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 12px;
    }
    .footer-bottom p {
      font-size: 0.813rem;
      color: rgba(255,255,255,0.4);
    }

    /* ─── SCROLL ANIMATIONS ─── */
    .animate-on-scroll {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 0.6s ease-out, transform 0.6s ease-out;
    }
    .animate-on-scroll.visible {
      opacity: 1;
      transform: translateY(0);
    }
    .stagger-1 { transition-delay: 0.1s; }
    .stagger-2 { transition-delay: 0.2s; }
    .stagger-3 { transition-delay: 0.3s; }
    .stagger-4 { transition-delay: 0.4s; }
    .stagger-5 { transition-delay: 0.5s; }
