  <script>
    // Initialize Lucide icons
    lucide.createIcons();

    // ─── STICKY HEADER SHADOW ───
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    }, { passive: true });

    // ─── MOBILE MENU ───
    const menuToggle = document.getElementById('menuToggle');
    const menuClose = document.getElementById('menuClose');
    const mobileOverlay = document.getElementById('mobileOverlay');
    const mobileMenu = document.getElementById('mobileMenu');

    function openMenu() {
      mobileOverlay.classList.add('open');
      mobileMenu.classList.add('open');
      document.body.style.overflow = 'hidden';
    }
    function closeMenu() {
      mobileOverlay.classList.remove('open');
      mobileMenu.classList.remove('open');
      document.body.style.overflow = '';
    }

    menuToggle.addEventListener('click', openMenu);
    menuClose.addEventListener('click', closeMenu);
    mobileOverlay.addEventListener('click', (e) => {
      if (e.target === mobileOverlay) closeMenu();
    });

    // ─── AUTOCOMPLETE SEARCH ───
    const searchInput = document.getElementById('searchInput');
    const dropdown = document.getElementById('autocompleteDropdown');
    const allItems = dropdown.querySelectorAll('.autocomplete-item');

    searchInput.addEventListener('input', () => {
      const val = searchInput.value.toLowerCase().trim();
      if (val.length === 0) {
        dropdown.classList.remove('visible');
        return;
      }
      let anyVisible = false;
      allItems.forEach(item => {
        const text = item.getAttribute('data-value').toLowerCase();
        const match = text.includes(val);
        item.style.display = match ? 'flex' : 'none';
        if (match) anyVisible = true;
      });
      dropdown.classList.toggle('visible', anyVisible);
    });

    searchInput.addEventListener('focus', () => {
      if (searchInput.value.trim().length > 0) {
        searchInput.dispatchEvent(new Event('input'));
      }
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.search-field')) {
        dropdown.classList.remove('visible');
      }
    });

    allItems.forEach(item => {
      item.addEventListener('click', () => {
        searchInput.value = item.getAttribute('data-value');
        dropdown.classList.remove('visible');
      });
    });

    // ─── SCROLL ANIMATIONS ───
    const animatedEls = document.querySelectorAll('.animate-on-scroll');
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });

    animatedEls.forEach(el => observer.observe(el));

    // ─── ANIMATED STAT COUNTERS ───
    function animateCounters() {
      const stats = document.querySelectorAll('.stat-number[data-target]');
      stats.forEach(stat => {
        const target = parseInt(stat.getAttribute('data-target'));
        const suffix = stat.getAttribute('data-suffix') || '';
        const duration = 2000;
        const start = performance.now();

        function formatNumber(n) {
          if (n >= 1000000) return (n / 1000000).toFixed(1) + '';
          if (n >= 1000) return n.toLocaleString();
          return n.toString();
        }

        function step(now) {
          const elapsed = now - start;
          const progress = Math.min(elapsed / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const current = Math.floor(eased * target);

          if (target >= 1000000) {
            stat.textContent = (eased * target / 1000000).toFixed(1) + 'M+';
          } else {
            stat.textContent = current.toLocaleString() + suffix;
          }

          if (progress < 1) requestAnimationFrame(step);
        }

        requestAnimationFrame(step);
      });
    }

    const statsSection = document.querySelector('.stats-bar');
    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          animateCounters();
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.3 });
    statsObserver.observe(statsSection);
  </script>
